function validate([s, k, queries]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 characters.';
  if (!/^[01]+$/.test(s)) return "s contains only '0' and '1'.";
  if (!Number.isInteger(k) || k < 1 || k > s.length) return 'k is between 1 and the length of s.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  const seen = new Set();
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2) return 'Each query is a pair [l, r].';
    const [l, r] = query;
    if (!Number.isInteger(l) || !Number.isInteger(r) || l < 0 || l > r || r >= s.length) return 'Each query has 0 <= l <= r < s.length.';
    if (seen.has(l + ',' + r)) return 'All queries are distinct.';
    seen.add(l + ',' + r);
  }
  return null;
}

