function countKConstraintSubstrings(s, k, queries) {
  const n = s.length;
  const firstBad = new Array(n).fill(n);
  const prefix = new Array(n + 1).fill(0);
  let zeros = 0;
  let ones = 0;
  let left = 0;
  for (let right = 0; right < n; right++) {
    if (s[right] === '0') {
      zeros++;
    } else {
      ones++;
    }
    while (zeros > k && ones > k) {
      if (s[left] === '0') {
        zeros--;
      } else {
        ones--;
      }
      firstBad[left] = right;
      left++;
    }
    prefix[right + 1] = prefix[right] + (right - left + 1);
  }
  const answer = [];
  for (const [l, r] of queries) {
    const split = Math.min(firstBad[l], r + 1);
    const span = split - l;
    answer.push(span * (span + 1) / 2 + prefix[r + 1] - prefix[split]);
  }
  return answer;
}

