function countKConstraintSubstrings(s, k, queries) {
  return queries.map(([l, r]) => {
    let total = 0;
    for (let a = l; a <= r; a++) {
      let zeros = 0;
      let ones = 0;
      for (let b = a; b <= r; b++) {
        if (s[b] === '0') zeros++;
        else ones++;
        if (zeros <= k || ones <= k) total++;
      }
    }
    return total;
  });
}

