function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 10000 : int(1, 10);
  // Bits come in runs: stay near 0 alternates them, stay near 1 makes long blocks of one bit.
  const stay = large ? 0.3 + rand() * 0.65 : rand() * 0.85;
  let bit = rand() < 0.5 ? '0' : '1';
  let s = '';
  for (let i = 0; i < n; i++) {
    if (i > 0 && rand() >= stay) bit = bit === '0' ? '1' : '0';
    s += bit;
  }
  const k = large ? (rand() < 0.5 ? int(1, 12) : int(13, 400)) : int(1, n);
  const q = large ? 2000 : int(1, Math.min(8, n * (n + 1) / 2));
  // Queries are distinct; large inputs mix short ranges with long ones.
  const seen = new Set();
  const queries = [];
  while (queries.length < q) {
    let l = int(0, n - 1);
    let r = int(0, n - 1);
    if (l > r) [l, r] = [r, l];
    if (large && rand() < 0.3) r = Math.min(n - 1, l + int(0, 40));
    if (seen.has(l + ',' + r)) continue;
    seen.add(l + ',' + r);
    queries.push([l, r]);
  }
  return [s, k, queries];
}
